// ---- generated placeholder artwork ----

const PALETTES: [string, string, string][] = [
  ['#1d3b53', '#3e7cb1', '#a7d3f2'], ['#3b1d4a', '#8e44ad', '#f0b3ff'], ['#4a2511', '#c0662b', '#ffd2a1'],
  ['#12402e', '#2e9e6b', '#b5f2d4'], ['#46141c', '#c0392b', '#ffb3a7'], ['#2b2f3a', '#5d6d7e', '#d5dbe1'],
  ['#0f3d3e', '#16a085', '#a3f7e8'], ['#3d3a12', '#b7950b', '#fff2a8'], ['#1b1f4a', '#3949ab', '#c5cbff'],
]

function hash(s: string) {
  let h = 2166136261
  for (let i = 0; i < s.length; i++) h = Math.imul(h ^ s.charCodeAt(i), 16777619)
  return h >>> 0
}

const esc = (s: string) => s.replace(/[&<>"']/g, c => `&#${c.charCodeAt(0)};`)

// A deterministic abstract image for a stub item (gradient, two soft shapes and, unless `label` is
// false, its name), as a data URL usable in <img> or CSS. Same seed, same picture.
export function stubArt(seed: string, w: number, h: number, opts: { label?: string | false; size?: number } = {}) {
  const r = hash(seed)
  const [dark, mid, light] = PALETTES[r % PALETTES.length]
  const a = (r >> 4) % 360
  const cx1 = ((r >> 8) % 100) / 100, cy1 = ((r >> 12) % 100) / 100
  const cx2 = ((r >> 16) % 100) / 100, cy2 = ((r >> 20) % 100) / 100
  const label = opts.label === false ? '' : (opts.label ?? seed)
  const fs = opts.size ?? Math.round(Math.min(w, h) * 0.14)
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${w}" height="${h}" viewBox="0 0 ${w} ${h}">`
    + `<defs><linearGradient id="g" gradientTransform="rotate(${a} .5 .5)"><stop offset="0" stop-color="${dark}"/><stop offset="1" stop-color="${mid}"/></linearGradient></defs>`
    + `<rect width="${w}" height="${h}" fill="url(#g)"/>`
    + `<circle cx="${cx1 * w}" cy="${cy1 * h}" r="${Math.max(w, h) * 0.45}" fill="${light}" opacity=".18"/>`
    + `<circle cx="${cx2 * w}" cy="${cy2 * h}" r="${Math.max(w, h) * 0.25}" fill="${dark}" opacity=".35"/>`
    + (label ? `<text x="50%" y="50%" fill="#fff" font-family="sans-serif" font-weight="600" font-size="${fs}" text-anchor="middle" dominant-baseline="middle">${esc(label)}</text>` : '')
    + `</svg>`
  return `data:image/svg+xml;charset=utf-8,${encodeURIComponent(svg)}`
}
